class Kvz < Formula
  desc "Native macOS Kubernetes: Linux, macOS and native pods in one cluster"
  homepage "https://github.com/kvz-platform/kvz"
  url "https://github.com/kvz-platform/kvz/releases/download/v1.37.2-2/kvz-v1.37.2-2-darwin-arm64.tar.gz"
  version "1.37.2-2"
  sha256 "77d02108eaae4afe9a47892b432ccc93bfa72555d6ecc6309262697c9594339d"

  depends_on arch: :arm64
  depends_on macos: :tahoe

  def install
    bin.install "bin/kvz"
    # config is the kernel's .config: kvz reads it to turn on CPU hotplug and cgroup limits
    (share/"kvz/kernel").install "share/kvz/kernel/Image", "share/kvz/kernel/config"
  end

  def caveats
    <<~EOS
      Start a cluster in this terminal:
        kvz server

      Or run it in the background and at login:
        kvz install server

      Then point kubectl at it:
        export KUBECONFIG=~/.kvz/kubeconfig.yaml
    EOS
  end

  test do
    assert_match "Kubernetes", shell_output("#{bin}/kvz version")
  end
end
